   btn.classList.add("wrong");btn.disabled=true;$("wFeedback").className="feedback bad";$("wFeedbackTitle").textContent="✗ נסה שוב";$("wFeedbackText").textContent=opt.why||"בדוק שוב את ההבדל בין האפשרויות.";return;
